// Filtra y normaliza el evento de Evolution
// Solo procesa: messages.upsert + fromMe=false + texto (conversation o extendedTextMessage)

const body = $input.item.json.body || $input.item.json;
const event = body.event;
const data = body.data;

// Solo procesar mensajes nuevos entrantes
if (event !== 'messages.upsert') {
  return { json: { skip: true, reason: `Evento ignorado: ${event}` } };
}

if (!data) {
  return { json: { skip: true, reason: 'Sin data' } };
}

// Ignorar mensajes propios (fromMe = true)
if (data.key?.fromMe === true) {
  return { json: { skip: true, reason: 'Mensaje propio (fromMe)' } };
}

// Extraer texto del mensaje (puede venir en varios formatos)
const msg = data.message || {};
const messageText = msg.conversation
  || msg.extendedTextMessage?.text
  || msg.imageMessage?.caption
  || msg.videoMessage?.caption
  || '';

if (!messageText.trim()) {
  return { json: { skip: true, reason: 'Mensaje no es texto (imagen/audio/sticker/etc)' } };
}

// Extraer datos del contacto
const remoteJid = data.key?.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@c.us', '');
const pushName = data.pushName || null;

// Ignorar grupos por ahora (terminan en @g.us)
if (remoteJid.includes('@g.us')) {
  return { json: { skip: true, reason: 'Mensaje de grupo (ignorados en Fase 1)' } };
}

return {
  json: {
    skip: false,
    message: messageText,
    contact_phone: phone,
    contact_name: pushName,
    remoteJid,
    instance: body.instance || 'excalando',
    messageId: data.key?.id
  }
};

// Toma la respuesta del Conversational y construye el payload para Evolution
const convResp = $input.item.json;
const original = $('Filtrar y normalizar evento').item.json;

const respuesta = convResp.respuesta || '(no respuesta)';

return {
  json: {
    number: original.contact_phone,
    text: respuesta,
    respuesta_metadata: convResp.metadata || {},
    original_message: original.message,
    contact_name: original.contact_name
  }
};
